<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    body { font: 16px system-ui, sans-serif; max-width: 760px; margin: 3rem auto; padding: 0 1rem; color: #182230; }
    h1 { margin-bottom: 1.5rem; }
    form { display: flex; gap: .6rem; align-items: end; }
    label { display: grid; gap: .35rem; }
    input, button, select { font: inherit; padding: .55rem .75rem; }
    button { cursor: pointer; }
    button:disabled, input:disabled { cursor: not-allowed; }
    #alert { color: #b42318; margin: 1rem 0; }
    .project-list, .task-list { padding: 0; list-style: none; }
    [data-testid="project-row"], [data-testid="task-row"] { display: flex; align-items: center; justify-content: space-between; gap: .75rem; border: 1px solid #d0d5dd; border-radius: 6px; padding: .75rem; margin: .6rem 0; }
  </style>
</head>
<body>
  <main id="app"></main>
  <script>
    const app = document.querySelector('#app');
    const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
    const normalizeSearch = value => String(value)
      .replace(/[ \t]+/g, ' ')
      .replace(/[A-Z]/g, char => String.fromCharCode(char.charCodeAt(0) + 32));
    const matchesSearch = (value, query) => {
      const normalizedQuery = normalizeSearch(String(query).trim());
      return normalizedQuery === '' || normalizeSearch(value).includes(normalizedQuery);
    };

    async function showProjects(navigate = true) {
      if (navigate && location.pathname !== '/') history.pushState({}, '', '/');
      const archived = new URLSearchParams(location.search).get('filter') === 'Archived';
      const query = (new URLSearchParams(location.search).get('q') || '').trim();
      const projects = await fetch(`/api/projects?archived=${archived}`).then(response => response.json());
      const matchingProjects = projects.filter(project => matchesSearch(project.name, query));
      app.innerHTML = `<h1>Workboard</h1>
        <form id="create-form"><label>Project name<input name="name" aria-label="Project name"></label><button type="submit">Create project</button></form>
        <p id="alert" role="alert" aria-live="polite"></p>
        <form id="project-search-form"><label>Project search<input id="project-search" aria-label="Project search" value="${escapeHtml(query)}"></label><button type="submit">Search projects</button></form>
        <label>Project filter<select id="project-filter" aria-label="Project filter"><option${archived ? '' : ' selected'}>Active</option><option${archived ? ' selected' : ''}>Archived</option></select></label>
        <ul class="project-list">${matchingProjects.map(project =>
          `<li class="project-row" data-testid="project-row"><span>${escapeHtml(project.name)}</span><span data-testid="project-summary">${project.completedCount}/${project.totalCount} completed</span><button type="button" data-open="${project.id}">Open project</button><button type="button" data-archive="${project.id}" data-value="${archived ? 'false' : 'true'}">${archived ? 'Restore project' : 'Archive project'}</button></li>`).join('')}</ul>`;
      app.querySelector('#project-filter').addEventListener('change', event => {
        const params = new URLSearchParams(location.search);
        if (event.currentTarget.value === 'Archived') params.set('filter', 'Archived');
        else params.delete('filter');
        if (query) params.set('q', query);
        else params.delete('q');
        history.pushState({}, '', '/' + (params.size ? `?${params}` : ''));
        showProjects(false);
      });
      app.querySelector('#project-search-form').addEventListener('submit', event => {
        event.preventDefault();
        const params = new URLSearchParams();
        if (archived) params.set('filter', 'Archived');
        const query = app.querySelector('#project-search').value.trim();
        if (query) params.set('q', query);
        history.pushState({}, '', '/' + (params.size ? `?${params}` : ''));
        showProjects(false);
      });
      app.querySelector('#create-form').addEventListener('submit', async event => {
        event.preventDefault();
        const name = new FormData(event.currentTarget).get('name').trim();
        if (!name) { app.querySelector('#alert').textContent = 'Project name is required'; return; }
        const response = await fetch('/api/projects', { method: 'POST', headers: {'content-type':'application/json'}, body: JSON.stringify({name}) });
        if (!response.ok) { app.querySelector('#alert').textContent = 'Project name is required'; return; }
        await showProjects();
      });
      app.querySelectorAll('[data-open]').forEach(button => button.addEventListener('click', () => openProject(button.dataset.open)));
      app.querySelectorAll('[data-archive]').forEach(button => button.addEventListener('click', async () => {
        await fetch(`/api/projects/${button.dataset.archive}/archive`, { method: 'PATCH', headers: {'content-type':'application/json'}, body: JSON.stringify({archived: button.dataset.value === 'true'}) });
        await showProjects(false);
      }));
    }

    async function openProject(id, navigate = true) {
      if (navigate && location.pathname !== `/projects/${id}`) history.pushState({}, '', `/projects/${id}`);
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      if (!response.ok) return showProjects();
      const project = await response.json();
      const locked = Boolean(project.archived);
      const activeProjects = await fetch('/api/projects?archived=false').then(response => response.json());
      const destinations = activeProjects.filter(item => String(item.id) !== String(id));
      app.innerHTML = `<button type="button" id="projects">Projects</button><h1>${escapeHtml(project.name)}</h1>
        ${locked ? '<p>Archived project</p>' : ''}<label>Default task priority<select id="default-priority" aria-label="Default task priority"${locked ? ' disabled' : ''}><option${project.defaultPriority === 'Low' ? ' selected' : ''}>Low</option><option${project.defaultPriority === 'Normal' ? ' selected' : ''}>Normal</option><option${project.defaultPriority === 'High' ? ' selected' : ''}>High</option></select></label><form id="rename-form"><label>New project name<input name="name" aria-label="New project name"${locked ? ' disabled' : ''}></label><button type="submit"${locked ? ' disabled' : ''}>Rename project</button></form>
        <form id="task-form"><label>Task title<input name="title" aria-label="Task title"${locked ? ' disabled' : ''}></label><button type="submit"${locked ? ' disabled' : ''}>Create task</button></form>
        <p id="alert" role="alert" aria-live="polite"></p>
        <label>Task filter<select id="task-filter" aria-label="Task filter"><option>All</option><option>Open</option><option>Completed</option><option>Deleted</option></select></label>
        <label>Priority filter<select id="priority-filter" aria-label="Priority filter"><option>All</option><option>Low</option><option>Normal</option><option>High</option></select></label>
        <form id="due-range-form"><label>Due from<input id="due-from" aria-label="Due from"></label><label>Due through<input id="due-through" aria-label="Due through"></label><button type="submit">Apply due range</button></form>
        <form id="task-search-form"><label>Task search<input id="task-search" aria-label="Task search"></label><button type="submit">Search tasks</button></form>
        <ul class="task-list" id="tasks"></ul>`;
      app.querySelector('#projects').addEventListener('click', showProjects);
      if (!locked) app.querySelector('#rename-form').addEventListener('submit', async event => {
        event.preventDefault();
        const name = new FormData(event.currentTarget).get('name').trim();
        if (!name) { app.querySelector('#alert').textContent = 'Project name is required'; return; }
        const result = await fetch(`/api/projects/${encodeURIComponent(id)}`, { method: 'PATCH', headers: {'content-type':'application/json'}, body: JSON.stringify({name}) });
        if (!result.ok) { app.querySelector('#alert').textContent = 'Project name is required'; return; }
        app.querySelector('h1').textContent = name;
      });
      const list = app.querySelector('#tasks');
      app.querySelector('#default-priority').addEventListener('change', async event => {
        await fetch(`/api/projects/${encodeURIComponent(id)}`, { method: 'PATCH', headers: {'content-type':'application/json'}, body: JSON.stringify({defaultPriority: event.currentTarget.value}) });
      });
      const filter = app.querySelector('#task-filter');
      const priorityFilter = app.querySelector('#priority-filter');
      let appliedFrom = '', appliedThrough = '', appliedTaskQuery = '';
      const isValidDate = value => {
        const match = value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
        if (!match) return false;
        const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
        const date = new Date(0); date.setUTCHours(0, 0, 0, 0); date.setUTCFullYear(year, month - 1, day);
        return year >= 1 && date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
      };
      app.querySelector('#due-range-form').addEventListener('submit', event => {
        event.preventDefault();
        const from = app.querySelector('#due-from').value.trim();
        const through = app.querySelector('#due-through').value.trim();
        const alert = app.querySelector('#alert');
        if ((from && !isValidDate(from)) || (through && !isValidDate(through))) { alert.textContent = 'Due range must use valid YYYY-MM-DD dates'; return; }
        if (from && through && from > through) { alert.textContent = 'Due from must not be after Due through'; return; }
        appliedFrom = from; appliedThrough = through; alert.textContent = ''; loadTasks();
      });
      async function loadTasks() {
        const tasks = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`).then(response => response.json());
        const shown = tasks.filter(task =>
          (filter.value === 'Deleted' ? Boolean(task.deleted) : !task.deleted && (filter.value === 'All' || (filter.value === 'Completed') === Boolean(task.completed))) &&
          (priorityFilter.value === 'All' || task.priority === priorityFilter.value) &&
          matchesSearch(task.title, appliedTaskQuery) &&
          ((!appliedFrom && !appliedThrough) || (Boolean(task.dueDate) && (!appliedFrom || task.dueDate >= appliedFrom) && (!appliedThrough || task.dueDate <= appliedThrough))));
        list.innerHTML = shown.map(task => `<li class="task-row" data-testid="task-row"><span>${escapeHtml(task.title)}</span><input type="checkbox" aria-label="Complete ${escapeHtml(task.title)}" data-task="${task.id}" ${task.completed ? 'checked' : ''}${locked || task.deleted ? ' disabled' : ''}><label>New task title<input aria-label="New task title" data-rename-title="${task.id}"${locked || task.deleted ? ' disabled' : ''}></label><button type="button" data-rename-task="${task.id}"${locked || task.deleted ? ' disabled' : ''}>Rename task</button><label>Task priority<select aria-label="Task priority" data-priority="${task.id}"${locked || task.deleted ? ' disabled' : ''}><option${task.priority === 'Low' ? ' selected' : ''}>Low</option><option${task.priority === 'Normal' ? ' selected' : ''}>Normal</option><option${task.priority === 'High' ? ' selected' : ''}>High</option></select></label><label>Task due date<input type="text" aria-label="Task due date" placeholder="YYYY-MM-DD" data-due-date="${task.id}" value="${escapeHtml(task.dueDate || '')}"${locked || task.deleted ? ' disabled' : ''}></label><button type="button" data-save-due="${task.id}"${locked || task.deleted ? ' disabled' : ''}>Save due date</button><label>Destination project<select aria-label="Destination project" data-destination="${task.id}"${locked || task.deleted || !destinations.length ? ' disabled' : ''}>${destinations.map(destination => `<option value="${destination.id}">${escapeHtml(destination.name)}</option>`).join('')}</select></label><button type="button" data-move-task="${task.id}"${locked || task.deleted || !destinations.length ? ' disabled' : ''}>Move task</button><button type="button" data-delete-task="${task.id}"${locked || task.deleted ? ' disabled' : ''}>Delete task</button><button type="button" data-restore-task="${task.id}"${locked || !task.deleted ? ' disabled' : ''}>Restore task</button><label>Task notes<textarea aria-label="Task notes" data-notes="${task.id}"${locked || task.deleted ? ' disabled' : ''}>${escapeHtml(task.notes || '')}</textarea></label><button type="button" data-save-notes="${task.id}"${locked || task.deleted ? ' disabled' : ''}>Save notes</button></li>`).join('');
        list.querySelectorAll('[data-delete-task], [data-restore-task]').forEach(button => button.addEventListener('click', async () => {
          const deleted = button.hasAttribute('data-delete-task');
          const taskId = deleted ? button.dataset.deleteTask : button.dataset.restoreTask;
          await fetch(`/api/tasks/${taskId}`, { method: 'PATCH', headers: {'content-type':'application/json'}, body: JSON.stringify({deleted}) });
          await loadTasks();
        }));
        list.querySelectorAll('[data-rename-task]').forEach(button => button.addEventListener('click', async () => {
          const title = list.querySelector(`[data-rename-title="${button.dataset.renameTask}"]`).value.trim();
          const alert = app.querySelector('#alert');
          if (!title) { alert.textContent = 'Task title is required'; return; }
          const result = await fetch(`/api/tasks/${button.dataset.renameTask}`, { method: 'PATCH', headers: {'content-type':'application/json'}, body: JSON.stringify({title}) });
          if (!result.ok) { alert.textContent = 'Task title is required'; return; }
          alert.textContent = '';
          await loadTasks();
        }));
        list.querySelectorAll('[data-save-notes]').forEach(button => button.addEventListener('click', async () => {
          const notes = list.querySelector(`[data-notes="${button.dataset.saveNotes}"]`).value;
          await fetch(`/api/tasks/${button.dataset.saveNotes}`, { method: 'PATCH', headers: {'content-type':'application/json'}, body: JSON.stringify({notes}) });
          await loadTasks();
        }));
        list.querySelectorAll('[data-save-due]').forEach(button => button.addEventListener('click', async () => {
          const dueDate = list.querySelector(`[data-due-date="${button.dataset.saveDue}"]`).value;
          const result = await fetch(`/api/tasks/${button.dataset.saveDue}`, { method: 'PATCH', headers: {'content-type':'application/json'}, body: JSON.stringify({dueDate}) });
          const alert = app.querySelector('#alert');
          if (!result.ok) { alert.textContent = 'Due date must be a valid YYYY-MM-DD date'; return; }
          alert.textContent = '';
          await loadTasks();
        }));
        list.querySelectorAll('[data-move-task]').forEach(button => button.addEventListener('click', async () => {
          const destination = list.querySelector(`[data-destination="${button.dataset.moveTask}"]`).value;
          await fetch(`/api/tasks/${button.dataset.moveTask}`, { method: 'PATCH', headers: {'content-type':'application/json'}, body: JSON.stringify({destinationProject: destination}) });
          await loadTasks();
        }));
        list.querySelectorAll('[data-priority]').forEach(select => select.addEventListener('change', async () => {
          await fetch(`/api/tasks/${select.dataset.priority}`, { method: 'PATCH', headers: {'content-type':'application/json'}, body: JSON.stringify({priority: select.value}) });
          await loadTasks();
        }));
        list.querySelectorAll('[data-task]').forEach(box => box.addEventListener('change', async () => {
          await fetch(`/api/tasks/${box.dataset.task}`, { method: 'PATCH', headers: {'content-type':'application/json'}, body: JSON.stringify({completed: box.checked}) });
          await loadTasks();
        }));
      }
      app.querySelector('#task-search-form').addEventListener('submit', event => {
        event.preventDefault();
        appliedTaskQuery = app.querySelector('#task-search').value.trim();
        loadTasks();
      });
      filter.addEventListener('change', loadTasks);
      priorityFilter.addEventListener('change', loadTasks);
      app.querySelector('#task-form').addEventListener('submit', async event => {
        event.preventDefault();
        if (locked) return;
        const form = event.currentTarget;
        const title = new FormData(form).get('title').trim();
        if (!title) { app.querySelector('#alert').textContent = 'Task title is required'; return; }
        const result = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: {'content-type':'application/json'}, body: JSON.stringify({title}) });
        if (!result.ok) { app.querySelector('#alert').textContent = 'Task title is required'; return; }
        form.reset();
        await loadTasks();
      });
      await loadTasks();
    }

    async function render() {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (match) await openProject(match[1], false);
      else await showProjects(false);
    }
    window.addEventListener('popstate', render);
    render();
  </script>
</body>
</html>
